public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = ThreadSnapshot.parseFromLine(line);
            if (threadSnapshot != null && isInTimeRange(threadSnapshot.getTimestamp(), timeRanges)) {
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}

/**
 * Checks if the given timestamp is in the given time range.
 *
 * @param timestamp the timestamp to check
 * @param timeRanges the time ranges to check against
 * @return true if the timestamp is in any of the time ranges, false otherwise
 */
private static boolean isInTimeRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
            return true;
        }
    }
    return false;
}
